/*
 * Lockfiles of the gallery's npm servers that install once instead of `npx -y`
 * at every start (review of 18/10, M10): exact version and `dist.integrity` of
 * every package, indirect ones included, all on the public registry.
 * Generated, do not edit by hand. To bump a server: in an empty folder with
 * `package.json` = `{"private":true,"dependencies":{"<package>":"<version>"}}`
 * run `npm install --package-lock-only --ignore-scripts --omit=dev
 * --registry=https://registry.npmjs.org/ --userconfig=<empty> --globalconfig=<empty>`
 * and put the new `package-lock.json` here (the test checks every entry).
 */

export interface NpmLock {
  name: string;
  lockfileVersion: number;
  requires: boolean;
  packages: Record<
    string,
    {
      version?: string;
      resolved?: string;
      integrity?: string;
      dependencies?: Record<string, string>;
      [field: string]: unknown;
    }
  >;
}

